-- 상세 설명(detailed_meaning) 재작성 2차 묶음 4: 119개 (id 377~500).
-- 한국은행 800선 원문을 해요체 3문장으로 새로 씀. detailed_meaning 한 열만 바꾸고 원문은 public.words_detailed_meaning_backup_v1에 남긴다.
-- DO 블록 하나: 실패하면 이 묶음 전체가 취소된다. 단어명·원문 글자 수가 검토 때와 다르면 중단한다.
DO $apply_v2_4$
DECLARE
  v_payload jsonb := $payload$[{"id": 377, "word": "에너지 믹스", "beforeLength": 450, "after": "한 나라가 쓰는 에너지를 원자력·석탄·가스·재생에너지 같은 여러 에너지원으로 어떤 비율씩 나눠 채우는지를 말해요. 정부는 비용, 환경 영향, 공급 안정성을 따져 목표 비율을 정하고 정책을 펴요. 최근에는 탄소 배출을 줄이려고 재생에너지 비중을 늘리는 쪽으로 조정하는 나라가 많아요."}, {"id": 378, "word": "엥겔의 법칙", "beforeLength": 629, "after": "소득이 낮은 가계일수록 전체 소비에서 먹거리에 쓰는 돈의 비중이 크다는 경험 법칙이에요. 음식은 꼭 사야 하지만 소득이 늘어도 그만큼 더 먹지는 않으니 비중이 점점 줄어들어요. 식료품비 비중을 엥겔계수라고 부르며 생활 수준을 가늠하는 데 쓰여요."}, {"id": 379, "word": "여신전문금융회사", "beforeLength": 537, "after": "예금은 받지 않고 돈을 빌려주거나 외상 구매를 돕는 일만 하는 금융회사예요. 신용카드사, 할부금융사, 리스사, 벤처 투자를 하는 신기술금융사가 여기에 속해요. 예금이 없으니 주로 채권을 발행하거나 돈을 빌려 영업 자금을 마련한다는 점이 은행과 달라요."}, {"id": 380, "word": "역모기지론", "beforeLength": 635, "after": "집을 가진 고령자가 그 집을 담보로 맡기고 매달 생활비를 연금처럼 받는 대출이에요. 받은 돈만큼 빚이 쌓이고, 나중에 본인과 배우자가 세상을 떠나면 금융기관이 집을 팔아 정산해요. 집을 사려고 빌린 뒤 갚아 나가는 일반 주택담보대출과 돈의 흐름이 반대예요."}, {"id": 381, "word": "역외펀드", "beforeLength": 521, "after": "우리나라가 아닌 외국 법에 따라 외국에서 만들어진 펀드예요. 세금이나 규제가 가벼운 지역에 서류상 회사를 세우고 실제 운용은 다른 곳에서 하는 경우가 많아요. 국내 법으로 만들어 해외 자산에 투자하는 해외투자펀드와는 적용받는 법이 달라요."}, {"id": 382, "word": "연구개발(R&D)", "beforeLength": 444, "after": "새로운 지식을 쌓고 그것으로 새 제품, 서비스, 생산 방법을 만들어 내는 체계적인 활동이에요. 기업, 대학, 정부가 수행하며 그 지출은 여러 해 동안 생산에 쓰이는 자산으로 보아 투자로 집계해요. 생산성을 높여 기업과 나라의 장기 성장력을 키우는 핵심 동력이에요."}, {"id": 383, "word": "연방준비제도(FRS)", "beforeLength": 552, "after": "1913년 법으로 만들어진 미국의 중앙은행 제도로 흔히 연준이라고 불러요. 워싱턴의 이사회와 금리를 정하는 연방공개시장위원회, 그리고 12개 지역 연방준비은행으로 이뤄져요. 연준의 금리 결정은 세계 금융시장과 환율에 큰 영향을 줘요."}, {"id": 384, "word": "연지급수입", "beforeLength": 132, "after": "수입한 물건이나 선적 서류를 받은 뒤 정해진 기간이 지나서 대금을 내는 조건의 수입이에요. 수입업자는 들여온 물건을 먼저 팔고 그 판매 대금으로 값을 치를 수 있어요. 그만큼 당장 마련해야 할 자금 부담이 줄어드는 외상 거래의 한 형태예요."}, {"id": 385, "word": "연차보고서", "beforeLength": 460, "after": "한국은행이 한 해 동안의 경제 흐름과 통화정책 운용 내용을 정리해 펴내는 법정 보고서예요. 한국은행법에 따라 매년 국회에 보고하며 금리 결정, 금융안정 조치, 연구 결과 등을 담아요. 누구나 홈페이지에서 볼 수 있어 중앙은행의 판단과 정책 방향을 알리는 창구가 돼요."}, {"id": 386, "word": "영끌", "beforeLength": 505, "after": "영혼까지 끌어모은다는 말을 줄인 표현으로, 동원할 수 있는 돈과 대출을 모두 모아 집이나 주식을 사는 것을 말해요. 신용대출, 마이너스통장은 물론 가족에게 빌린 돈까지 보태는 경우가 많아요. 금리가 오르거나 자산값이 떨어지면 빚 부담이 크게 늘어 위험해요."}, {"id": 387, "word": "영업잉여", "beforeLength": 177, "after": "생산 활동으로 생긴 소득 가운데 일한 사람에게 주는 임금을 빼고 자본과 경영 쪽에 돌아가는 몫이에요. 국민소득은 노동의 대가인 피용자보수와 이 몫으로 나뉘어요. 기업이 생산으로 벌어들인 이윤에 가까운 개념이라고 보면 돼요."}, {"id": 388, "word": "예금보험제도", "beforeLength": 738, "after": "금융회사가 문을 닫아 예금을 돌려주지 못할 때 예금보험공사가 대신 지급해 주는 제도예요. 금융회사는 평소 보험료를 내고, 예금자는 한 금융회사당 원금과 이자를 합쳐 정해진 한도까지 보호받아요. 돈을 잃을까 봐 한꺼번에 예금을 빼 가는 뱅크런을 막는 안전장치 역할을 해요."}, {"id": 389, "word": "예금취급기관", "beforeLength": 672, "after": "고객에게 예금을 받고 그 돈으로 대출을 해 주는 금융기관을 말해요. 일반 은행과 특수은행, 그리고 저축은행·신협·새마을금고·상호금융 같은 비은행 기관이 여기에 들어가요. 예금이 대출로 돌고 다시 예금이 되는 과정에서 시중의 돈을 늘리는 역할도 해요."}, {"id": 390, "word": "예금토큰", "beforeLength": 237, "after": "은행이 고객 예금을 바탕으로 블록체인 같은 분산원장 기술을 써서 발행하는 디지털 화폐예요. 같은 금액의 예금이 뒷받침하므로 언제든 일반 예금으로 되바꿀 수 있어요. 결제를 더 빠르고 싸게 만들 수 있어 중앙은행과 은행들이 실험하고 있는 새로운 결제 수단이에요."}, {"id": 391, "word": "예대금리차(예대마진)", "beforeLength": 416, "after": "은행이 대출해 주고 받는 금리에서 예금자에게 주는 금리를 뺀 차이예요. 예를 들어 대출금리가 5%, 예금금리가 3%라면 차이는 2%포인트이고 이것이 은행 수익의 기본 원천이 돼요. 은행 간 경쟁이 약하거나 빌려준 돈을 떼일 위험이 클수록 차이가 커지는 경향이 있어요."}, {"id": 392, "word": "예대율", "beforeLength": 415, "after": "은행이 받은 예금에 비해 대출을 얼마나 내주었는지 보여 주는 비율이에요. 단순하게는 대출금을 예금으로 나눠 100을 곱하고, 규제에서는 대출 종류별로 가중치를 달리 적용해요. 비율이 너무 높으면 예금보다 대출이 많아 자금 사정이 불안해질 수 있어 감독당국이 상한을 둬요."}, {"id": 393, "word": "예상손실", "beforeLength": 221, "after": "일정 기간 동안 평균적으로 생길 것으로 예상되는 손실 금액이에요. 떼일 수 있는 금액에 부도가 날 확률과 부도 때 실제로 잃는 비율을 곱해서 구해요. 금융회사는 이렇게 미리 예상되는 손실에 대비해 충당금을 쌓아 둬요."}, {"id": 394, "word": "예약자금이체제도", "beforeLength": 347, "after": "금융기관이 미리 신청해 둔 자금이체를 정해진 미래 시점이 되면 자동으로 결제해 주는 제도예요. 원래 한은금융망은 지급 지시를 받는 즉시 처리하지만, 이 제도로 결제 시점을 미리 예약할 수 있어요. 차액결제 때 자금이 모자란 기관이 다른 기관에서 제때 돈을 받는 데도 쓰여요."}, {"id": 395, "word": "오픈뱅킹", "beforeLength": 373, "after": "고객이 동의하면 은행이 가진 계좌 정보와 이체 기능을 다른 금융 앱에도 열어 주는 제도예요. 표준화된 연결 통로인 API를 통해 앱 하나로 여러 은행 계좌를 조회하고 이체할 수 있어요. 우리나라는 2019년 개인 대상으로 시작했고 이후 법인까지 넓어졌어요."}, {"id": 396, "word": "옵션", "beforeLength": 737, "after": "미리 정한 가격으로 정해진 시점에 어떤 자산을 사거나 팔 수 있는 권리를 사고파는 계약이에요. 살 권리는 콜옵션, 팔 권리는 풋옵션이며 권리를 산 사람은 유리할 때만 행사하고 불리하면 포기해요. 그 선택권의 대가로 파는 사람에게 프리미엄을 내는 것이 특징이에요."}, {"id": 397, "word": "와타나베 부인", "beforeLength": 541, "after": "금리가 낮은 엔화를 빌려 외화로 바꾼 뒤 금리가 높은 해외 자산에 투자하는 일본 개인투자자를 부르는 말이에요. 일본의 오랜 저금리 속에서 2000년 무렵 가계 살림을 맡은 주부들 사이에서 퍼졌어요. 규모가 커지면서 환율에 영향을 줄 만큼 외환시장의 큰손으로 여겨졌어요."}, {"id": 398, "word": "완충자본", "beforeLength": 687, "after": "은행이 최소로 갖춰야 하는 자기자본 위에 위기에 대비해 추가로 쌓아 두는 자본이에요. 이 기준을 못 채우면 채울 때까지 배당이나 성과급 같은 이익 배분이 제한돼요. 평소에 쌓았다가 위기 때 꺼내 쓰게 해서 은행이 손실을 견디며 대출을 계속하도록 도와요."}, {"id": 399, "word": "외국환거래법", "beforeLength": 565, "after": "외환 거래를 원칙적으로 자유롭게 허용하고 꼭 필요한 부분만 제한하는 우리나라의 외환 기본법이에요. 1997년 외환위기 이후 엄격히 통제하던 옛 외국환관리법을 대신해 도입됐어요. 대신 급격한 자본 유출입에 대비해 위기 때 쓸 수 있는 안정 장치도 함께 두고 있어요."}, {"id": 400, "word": "외국환은행(외국환업무취급기관)", "beforeLength": 538, "after": "자본, 전산 설비, 전문 인력 요건을 갖추고 기획재정부에 등록해 외환 업무를 하는 금융기관을 말해요. 이 가운데 은행법상 은행과 산업은행, 수출입은행, 기업은행 등의 국내 영업소가 외국환은행에 해당해요. 이 은행들은 환전, 송금 같은 외환 업무를 대부분 할 수 있어요."}, {"id": 402, "word": "외국환평형기금", "beforeLength": 433, "after": "환율을 안정시키고 투기성 자금의 급격한 유출입을 막으려고 정부가 외환시장에 개입할 때 쓰는 기금이에요. 원화 계정과 외화 계정으로 나뉘며 주로 다른 정부 기금에서 빌리거나 전용 채권을 발행해 돈을 마련해요. 환율이 급등락할 때 외화를 사고팔아 시장 충격을 줄이는 데 쓰여요."}, {"id": 403, "word": "외국환포지션", "beforeLength": 500, "after": "은행이나 기업이 가진 외화자산과 외화부채의 차이로, 환율 변동 위험에 얼마나 노출됐는지 보여 줘요. 자산이 더 많으면 매입초과, 부채가 더 많으면 매도초과, 같으면 스퀘어 포지션이라고 해요. 외환당국은 은행별로 이 차이에 한도를 두어 과도한 위험을 막아요."}, {"id": 404, "word": "외국환포지션한도", "beforeLength": 456, "after": "외국환은행이 가진 외화자산과 외화부채의 차이를 자기자본의 일정 비율 안으로 묶어 두는 규제예요. 예컨대 달러 자산이 더 많은 은행은 환율이 떨어지면 손실을 보므로 차이가 클수록 위험도 커져요. 한 은행의 지나친 쏠림이 외환시장을 흔들지 않도록 미리 막는 장치예요."}, {"id": 405, "word": "외부자금", "beforeLength": 420, "after": "기업이 은행 대출이나 회사채 발행처럼 회사 밖에서 끌어온 자금이에요. 이익을 쌓아 둔 내부자금과 달리 이자와 절차 비용이 들고 갚을 기한도 있어요. 대신 규모 제약이 적어 큰 설비 투자를 할 때 많이 쓰여요."}, {"id": 406, "word": "외부효과", "beforeLength": 578, "after": "한 사람이나 기업의 행동이 대가를 주고받지 않은 채 다른 사람에게 이익이나 피해를 주는 현상이에요. 공장 매연은 피해를 주는 부정적인 예이고, 교육이나 신기술처럼 주변에 이익을 주는 긍정적인 예도 있어요. 시장에 맡겨 두면 해로운 활동은 너무 많고 이로운 활동은 너무 적어지기 쉬워요."}, {"id": 407, "word": "외화자금시장", "beforeLength": 443, "after": "금리를 대가로 외화를 빌리고 빌려주는 시장이에요. 대표적인 것이 외환스왑과 통화스왑 시장으로, 겉으로는 통화를 바꾸지만 실제로는 가진 통화를 맡기고 필요한 통화를 빌리는 거래예요. 환율을 매개로 통화를 사고파는 외환시장과 구분돼요."}, {"id": 408, "word": "외환건전성부담금제도", "beforeLength": 564, "after": "금융기관이 예금이 아닌 방식으로 빌린 외화부채에 부담금을 매기는 제도로 2011년 도입됐어요. 외화 차입을 늘릴수록 비용이 들게 해 지나친 단기 차입을 억제하고 만기가 긴 차입을 유도해요. 걷은 부담금은 외국환평형기금에 쌓여 위기 때 외화 유동성 지원에 쓰여요."}, {"id": 409, "word": "외환동시결제(PVP)", "beforeLength": 288, "after": "외환 거래에서 내가 줄 통화와 받을 통화를 서로 연결해 동시에 주고받는 결제 방식이에요. 상대 통화를 받는 것이 확실할 때만 내 통화를 내보내므로 한쪽만 돈을 보내는 일이 생기지 않아요. 나라마다 결제 시간이 달라 생기는 원금 손실 위험을 줄여 주며 CLS은행이 대표적이에요."}, {"id": 410, "word": "외환보유액", "beforeLength": 586, "after": "중앙은행과 정부가 비상시 언제든 쓸 수 있도록 쌓아 둔 외화 자산이에요. 환율이 급등하거나 금융기관이 해외에서 돈을 빌리기 어려워질 때 시장에 외화를 공급하는 재원이 돼요. 넉넉하면 나라 신용도를 받쳐 주지만 쌓아 두는 데 비용도 들어 적정 규모를 관리해야 해요."}, {"id": 411, "word": "외환스왑거래", "beforeLength": 498, "after": "지금 정한 환율로 두 통화를 맞바꾸고, 일정 기간 뒤 미리 정한 환율로 다시 되바꾸는 거래예요. 기간 중 이자는 따로 주고받지 않고 두 통화의 금리 차이를 만기 환율에 반영해요. 기업과 은행이 필요한 외화를 잠시 조달하거나 환율 위험을 관리할 때 많이 써요."}, {"id": 412, "word": "외환시장", "beforeLength": 534, "after": "원화와 달러처럼 서로 다른 나라 통화를 사고파는 시장이에요. 무역이나 해외 투자로 생기는 외화 수요와 공급이 만나 환율이 정해져요. 세계 주요 시장이 시간대를 이어 가며 24시간 거래되는 하나의 큰 시장처럼 움직여요."}, {"id": 413, "word": "외환전산망", "beforeLength": 602, "after": "외국환업무를 하는 금융기관의 외환 거래 정보를 한국은행에 모으는 전산 시스템이에요. 외환위기 이후 자본 이동이 자유로워지자 1999년 만들어졌고, 모은 정보는 정부와 감독기관 등에 제공돼요. 외화 유출입을 빠르게 살피고 외환 통계 작성이나 불법 거래 조사에 활용돼요."}, {"id": 414, "word": "요소비용", "beforeLength": 446, "after": "시장가격에서 부가가치세 같은 생산·수입 관련 세금을 빼고 정부 보조금을 더한 금액이에요. 이렇게 하면 상품을 만드는 데 들어간 노동과 자본에 실제로 돌아간 몫만 남아요. 세금 때문에 부풀거나 보조금 때문에 줄어든 부분을 걷어 내 생산 기여를 정확히 보려는 개념이에요."}, {"id": 415, "word": "요소비용 국민소득", "beforeLength": 267, "after": "국민이 노동과 자본 같은 생산요소를 제공하고 벌어들인 소득을 모두 더한 값으로, 흔히 국민소득이라고 불러요. 일한 대가인 피용자보수와 기업 몫인 영업잉여를 합쳐 계산해요. 세금과 설비 마모분이 빠져 있어 국민이 실제로 번 순수한 소득을 보여 줘요."}, {"id": 416, "word": "우발부채(채무)", "beforeLength": 476, "after": "지금은 확정되지 않았지만 앞으로 어떤 일이 생기면 갚아야 할 수도 있는 잠재적인 빚이에요. 남의 빚에 선 지급보증이나 진행 중인 소송에서 질 가능성 같은 것이 대표적이에요. 금액과 시기가 불확실해 재무제표에 부채로 올리지 않고 주석으로 따로 적어요."}, {"id": 417, "word": "우발전환사채(코코본드)", "beforeLength": 677, "after": "발행한 금융회사가 부실해지면 원금이 깎이거나 주식으로 바뀌는 조건이 붙은 채권이에요. 그 조건이 발동되면 회사의 빚은 줄고 자본은 늘어나 위기를 견디는 데 도움이 돼요. 투자자는 원금을 잃을 위험을 지는 대신 일반 회사채보다 높은 금리를 받아요."}, {"id": 418, "word": "운영리스크", "beforeLength": 482, "after": "회사 내부의 업무 절차, 사람, 전산 시스템이 잘못되거나 외부 사건이 터져서 손실이 날 위험이에요. 직원 실수나 횡령, 시스템 장애, 해킹, 자연재해 등이 원인이 될 수 있어요. 시장 가격 변동이나 거래 상대의 부도에서 오는 위험과 구분해서 관리해요."}, {"id": 419, "word": "워싱턴 컨센서스", "beforeLength": 591, "after": "1990년대 미국이 경제위기를 겪던 중남미 국가들에 제시한 시장 중심의 경제개혁 처방이에요. 미국 재무부, IMF, 세계은행 등 워싱턴에 있는 기관들이 무역 개방, 민영화, 규제 완화, 재정 긴축을 권했어요. 신자유주의를 대표하는 말로 쓰이며 부작용이 컸다는 비판도 받았어요."}, {"id": 420, "word": "워크아웃", "beforeLength": 498, "after": "빚을 갚기 어려워진 기업을 채권 금융기관과 협의해 되살리는 재무구조 개선 절차예요. 기업은 자산 매각과 사업 정리로 몸집을 줄이고, 채권단은 상환 유예나 이자 감면, 대출의 주식 전환으로 도와요. 법원이 주도하는 법정관리와 달리 채권단 협의로 진행된다는 점이 특징이에요."}, {"id": 421, "word": "원·위안 직거래시장", "beforeLength": 675, "after": "달러를 거치지 않고 원화와 위안화를 바로 사고파는 외환시장이에요. 한국과 중국이 서로의 통화 사용을 늘리기로 합의하면서 2014년 서울에 개설됐어요. 달러를 두 번 거치는 환전 비용과 달러 환율 변동의 영향을 줄일 수 있어요."}, {"id": 422, "word": "원금리스크", "beforeLength": 221, "after": "외환 거래에서 내 통화는 이미 보냈는데 상대가 파산해 받기로 한 통화를 전액 못 받을 위험이에요. 두 통화가 서로 다른 나라에서 다른 시간대에 결제되다 보니 주고받는 시점이 어긋나서 생겨요. 외환 결제에서 가장 대표적인 위험이라 동시결제 방식으로 줄이려고 해요."}, {"id": 423, "word": "원금이자분리채권(STRIPS)", "beforeLength": 568, "after": "이자를 주기적으로 주는 채권에서 원금과 각 이자를 따로 떼어 별개의 채권처럼 거래하게 한 것이에요. 떼어 낸 조각은 만기에 한 번만 돈을 받는 할인채처럼 되어 다양한 만기의 상품이 생겨요. 중간에 받은 이자를 다시 굴릴 걱정이 없어 투자 시점에 수익률을 확정할 수 있어요."}, {"id": 424, "word": "위조지폐", "beforeLength": 260, "after": "진짜 돈처럼 보이게 스캐너나 프린터 등으로 몰래 만든 가짜 지폐예요. 돈으로 쓰려고 지폐를 위조하면 형법에 따라 무거운 징역형을 받아요. 한국은행은 홀로그램, 색이 변하는 잉크, 숨은 은선 같은 위조방지 장치를 지폐에 넣어 이를 막아요."}, {"id": 425, "word": "위험가중자산", "beforeLength": 406, "after": "은행 자산마다 떼일 위험의 크기에 따라 가중치를 곱해 더한 금액이에요. 예를 들어 국채처럼 안전한 자산은 낮은 가중치를, 위험한 대출은 높은 가중치를 받아요. 자기자본비율을 계산할 때 분모로 쓰여 위험한 자산이 많을수록 더 많은 자본을 갖추게 해요."}, {"id": 427, "word": "유동비율", "beforeLength": 158, "after": "1년 안에 현금으로 바꿀 수 있는 유동자산을 1년 안에 갚아야 할 유동부채로 나눈 비율이에요. 비율이 높을수록 곧 돌아올 빚을 갚을 능력이 좋다고 봐요. 다만 너무 높으면 돈을 놀리고 있다는 뜻이라 수익성이 떨어질 수 있어요."}, {"id": 428, "word": "유동성 함정", "beforeLength": 226, "after": "금리가 이미 아주 낮아 중앙은행이 돈을 더 풀어도 소비와 투자가 늘지 않는 상태예요. 사람들이 늘어난 돈을 쓰지 않고 현금으로 쥐고 있으려 해서 금리 인하 효과가 실물경제로 이어지지 않아요. 이럴 때는 통화정책만으로 경기를 살리기 어려워 재정정책의 역할이 커져요."}, {"id": 429, "word": "유동성리스크", "beforeLength": 197, "after": "일시적으로 돈이 모자라 약속한 시점에 결제를 하지 못할 위험이에요. 이 때문에 돈을 받기로 한 상대방의 자금 계획까지 꼬일 수 있어요. 시간이 지나면 결국 갚을 수 있다는 점에서 상대가 망해 영영 못 받는 신용리스크와 구분돼요."}, {"id": 430, "word": "유동성커버리지비율", "beforeLength": 518, "after": "심각한 위기가 30일 동안 이어져도 은행이 버틸 만큼 현금성 자산을 갖고 있는지 보는 비율이에요. 현금, 국채, 지급준비금 같은 고유동성자산을 30일간 빠져나갈 순현금으로 나눠 계산해요. 100% 이상이면 한 달간의 자금 유출을 스스로 감당할 수 있다는 뜻이에요."}, {"id": 431, "word": "유럽부흥개발은행(EBRD)", "beforeLength": 466, "after": "옛 사회주의 국가였던 중·동부 유럽 나라들이 시장경제로 바뀌도록 돕기 위해 1991년 세운 국제금융기구예요. 본부는 영국 런던에 있고 주로 민간 기업에 대출이나 투자를 하며 기술 지원도 해요. 정부보다 민간 부문을 키우는 데 초점을 둔다는 점이 다른 개발은행과 달라요."}, {"id": 432, "word": "유럽연합(EU)", "beforeLength": 739, "after": "유럽 국가들이 경제와 정치를 하나로 묶기 위해 만든 공동체로 1993년 마스트리히트 조약이 발효되며 출범했어요. 회원국끼리는 사람, 상품, 서비스, 자본이 자유롭게 오가는 단일시장을 이뤄요. 일부 회원국은 유로라는 단일 통화도 함께 써요."}, {"id": 433, "word": "유럽중앙은행(ECB)", "beforeLength": 410, "after": "유로화를 쓰는 나라들의 통화정책을 맡는 중앙은행으로 1998년 출범했고 본부는 독일 프랑크푸르트에 있어요. 유로존 전체에 적용되는 기준금리를 정하고 유로화 지폐 발행 권한을 가져요. 가장 중요한 목표는 유로존의 물가 안정이에요."}, {"id": 434, "word": "유로달러(Euro dollar)", "beforeLength": 544, "after": "미국이 아닌 다른 나라의 은행에 예치되어 거래되는 미국 달러를 말해요. 냉전 시기 동유럽 은행들이 미국에 두었던 달러를 유럽으로 옮기면서 시작됐고 런던이 중심지가 됐어요. 이름과 달리 유로화와는 상관없고 미국 규제 밖에 있는 달러라는 점이 핵심이에요."}, {"id": 435, "word": "유로마켓(Euro market)", "beforeLength": 511, "after": "어떤 통화가 그 통화를 발행한 나라 밖에서 거래되는 국제금융시장이에요. 예를 들어 미국 밖에서 달러로 예금하고 대출하거나 채권을 발행하는 거래가 여기에 들어가요. 발행국의 규제를 덜 받아 국내 시장과 분리된 순수한 국제시장이라는 특징이 있어요."}, {"id": 436, "word": "유통시장", "beforeLength": 706, "after": "이미 발행된 주식이나 채권을 투자자들끼리 사고파는 시장이에요. 거래소에서 거래하는 장내시장과 증권사 중개로 거래하는 장외시장이 있어요. 언제든 팔 수 있게 해 주므로 투자자가 새로 발행되는 증권을 사는 발행시장도 함께 살아나요."}, {"id": 437, "word": "은선", "beforeLength": 558, "after": "위조를 막으려고 지폐 용지 속에 넣은 가는 플라스틱이나 금속 필름 띠예요. 종이 속에 완전히 숨은 것과 앞뒤로 들락날락하며 보이는 것이 있고, 안에 작은 글자나 무늬를 넣기도 해요. 빛에 비추거나 각도를 바꿔 보면 확인할 수 있어 진짜 돈을 가리는 단서가 돼요."}, {"id": 438, "word": "은행경영공시제도", "beforeLength": 302, "after": "은행이 경영 실적과 재무 건전성 같은 중요한 정보를 정기적으로 공개하도록 한 제도예요. 결산 뒤 정해진 기간 안에 재무와 손익, 자금 운용, 수익성 지표, 리스크 관리 내용 등을 알려야 해요. 예금자와 주주가 정보를 보고 은행을 감시하게 해 감독당국의 감독을 보완해요."}, {"id": 439, "word": "은행인수어음(BA)", "beforeLength": 308, "after": "수출입 대금을 치르려고 발행한 환어음을 은행이 대신 지급하겠다고 약속해 준 어음이에요. 은행이 지급 책임을 지므로 신용도가 높아 시장에서 자유롭게 사고팔 수 있어요. 무역 기업에는 단기 자금을 구하는 통로이고 투자자에게는 안전한 단기 투자 수단이 돼요."}, {"id": 440, "word": "을기금(Capital B)", "beforeLength": 324, "after": "외국은행 국내지점이 대출 한도 등을 계산할 때 자기자본으로 인정받는 명목상의 자본금이에요. 외화를 되사는 조건으로 한국은행에 팔아 마련한 원화나 본점에서 장기로 빌려 와 국내에서 쓰는 돈이 해당해요. 재무상태표에는 나타나지 않지만 지점의 대출 여력을 넓혀 줘요."}, {"id": 441, "word": "의중임금", "beforeLength": 358, "after": "일할 생각이 있는 사람이 일자리를 받아들이려면 최소한 이만큼은 받아야 한다고 여기는 임금이에요. 제안받은 임금이 이 수준보다 높으면 취업하고 낮으면 계속 일자리를 찾거나 구직을 포기해요. 이 기준이 높을수록 일자리를 고르는 기간이 길어져 실업 기간에 영향을 줘요."}, {"id": 442, "word": "이구환신", "beforeLength": 429, "after": "오래된 물건을 새것으로 바꾼다는 뜻의 중국 소비 촉진 정책이에요. 낡은 가전제품이나 자동차를 새 제품으로 교체하면 보조금이나 금융 지원을 줘요. 침체된 소비를 살리는 동시에 에너지를 많이 쓰는 낡은 제품을 줄이는 효과를 노려요."}, {"id": 443, "word": "이슬람금융", "beforeLength": 480, "after": "이자를 받는 것을 금지하는 이슬람 율법 샤리아에 따라 운영되는 금융이에요. 이자 대신 실물 자산을 사고팔거나 빌려주는 거래, 사업 수익을 나누는 방식으로 돈을 굴려요. 모든 상품은 율법 학자들로 구성된 위원회에서 율법에 맞는지 미리 인증받아야 해요."}, {"id": 444, "word": "이연차액결제", "beforeLength": 322, "after": "일정 기간 주고받을 금액을 모아 서로 상계한 뒤 남는 차액만 나중에 한 번에 결제하는 방식이에요. 예를 들어 A은행이 100을 주고 80을 받을 일이 있다면 20만 보내면 돼요. 필요한 결제 자금은 적지만 결제 시점까지 상대가 못 갚을 위험이 남아 있어요."}, {"id": 445, "word": "이자보상배율", "beforeLength": 383, "after": "기업이 영업으로 번 이익을 이자 비용으로 나눈 값으로, 이자를 감당할 힘을 보여 줘요. 배율이 1이면 번 돈을 모두 이자로 내야 하고, 1보다 작으면 영업이익으로 이자도 못 갚는다는 뜻이에요. 이런 상태가 몇 년씩 이어지는 기업을 흔히 한계기업이라고 불러요."}, {"id": 446, "word": "이전소득수지", "beforeLength": 143, "after": "외국과 아무 대가 없이 주고받은 돈의 차이를 나타내는 경상수지 항목이에요. 해외 교포가 국내 가족에게 보내는 송금, 외국 자선단체의 기부금, 국제기구 출연금 등이 포함돼요. 상품이나 서비스, 노동의 대가가 아니라는 점에서 다른 경상수지 항목과 달라요."}, {"id": 447, "word": "이중통화채(Dual Currency Bond)", "beforeLength": 558, "after": "채권을 발행하고 이자를 줄 때와 원금을 갚을 때 서로 다른 통화를 쓰는 채권이에요. 보통 금리가 낮은 통화로 발행하고 금리가 높은 통화로 상환하며 상환 환율은 미리 정해 둬요. 발행자는 이자 부담을 줄이고, 투자자는 상환 통화가 강해지면 환차익을 기대할 수 있어요."}, {"id": 448, "word": "이차전지", "beforeLength": 512, "after": "한 번 쓰고 버리는 건전지와 달리 충전해서 여러 번 다시 쓸 수 있는 전지예요. 밖에서 받은 전기 에너지를 화학 에너지로 바꿔 저장했다가 필요할 때 다시 전기로 꺼내 써요. 스마트폰, 전기차, 에너지저장장치에 들어가는 핵심 부품이라 관련 산업이 크게 주목받아요."}, {"id": 449, "word": "이표채", "beforeLength": 676, "after": "만기까지 정해진 주기마다 이자를 주고 만기에 원금을 돌려주는 채권이에요. 옛날에는 채권에 붙은 이자표, 즉 쿠폰을 떼어 내 이자를 받았던 데서 이름이 붙었어요. 가장 흔한 채권 형태이며 처음부터 이자만큼 깎아 파는 할인채와 대비돼요."}, {"id": 450, "word": "익스포저", "beforeLength": 593, "after": "특정 위험에 노출되어 손실을 볼 수 있는 금액을 말해요. 금리나 환율 변동에 걸린 금액은 시장리스크 익스포저, 거래 상대의 부도에 걸린 금액은 신용리스크 익스포저예요. 장부에 잡힌 자산뿐 아니라 지급보증처럼 장부 밖 약정까지 포함해 장부 금액보다 넓은 개념이에요."}, {"id": 452, "word": "인적자본", "beforeLength": 665, "after": "교육과 훈련, 경험을 통해 사람에게 쌓인 지식과 기술, 능력을 자본에 빗대어 부르는 말이에요. 기계에 투자하면 생산이 늘듯 교육에 투자하면 노동의 질이 높아져 더 많이 생산할 수 있어요. 1960년대 경제학자 슐츠가 경제성장을 설명하는 핵심 요소로 강조한 개념이에요."}, {"id": 453, "word": "인터넷뱅킹", "beforeLength": 292, "after": "은행에 가지 않고 인터넷으로 계좌 조회, 이체, 대출 같은 은행 업무를 처리하는 서비스예요. 휴대전화로 이용하는 모바일뱅킹도 넓게 보면 여기에 포함돼요. 시간과 장소에 구애받지 않아 지금은 가장 흔한 은행 거래 방식이 됐어요."}, {"id": 454, "word": "인플레이션", "beforeLength": 239, "after": "물가가 전반적으로, 그리고 지속적으로 오르는 현상이에요. 여러 상품 가격을 평균한 물가지수가 계속 올라가면 같은 돈으로 살 수 있는 물건이 줄어들어요. 한두 상품만 오르는 것이 아니라 전체 물가가 꾸준히 오른다는 점이 핵심이에요."}, {"id": 455, "word": "인플레이션감축법(IRA)", "beforeLength": 836, "after": "높은 물가에 대응하고 기후변화에 대비하려고 미국이 2022년 시행한 법이에요. 의약품 가격 인하와 함께 전기차, 배터리, 재생에너지 같은 청정에너지 분야에 대규모 세액공제를 담았어요. 일부 혜택이 북미 생산 같은 조건과 묶여 있어 우리 기업의 투자 전략에도 영향을 줬어요."}, {"id": 456, "word": "일대일로", "beforeLength": 709, "after": "중국에서 출발해 아시아, 아프리카, 유럽을 육로와 바닷길로 잇겠다는 중국의 대규모 경제권 구상이에요. 육상 실크로드 경제벨트와 해상 실크로드를 축으로 도로, 철도, 항만 같은 기반시설 건설을 지원해요. 참여국과의 교류를 넓히는 효과가 있지만 상대국 빚 부담을 키운다는 비판도 받아요."}, {"id": 457, "word": "일물일가의 법칙", "beforeLength": 545, "after": "거래비용이나 무역장벽이 없다면 같은 상품은 어디서든 같은 통화 기준으로 같은 가격이 된다는 법칙이에요. 한 곳이 더 싸면 그곳에서 사서 비싼 곳에 파는 차익거래가 일어나 가격 차이가 사라져요. 환율이 각국 물가 수준에 맞춰진다는 구매력평가설의 바탕이 돼요."}, {"id": 458, "word": "일반특혜관세", "beforeLength": 369, "after": "선진국이 개발도상국에서 들여오는 상품에 관세를 낮추거나 없애 주는 특혜 제도예요. 정해진 품목과 원산지 기준을 충족해야 하며 특정 몇 나라가 아닌 개발도상국 전반에 적용돼요. 개발도상국의 수출을 늘려 산업화를 돕는 것이 목적이에요."}, {"id": 459, "word": "일중RP제도", "beforeLength": 613, "after": "중앙은행이 국채 같은 증권을 사 주고 그날 안에 되팔게 하는 방식으로 금융기관에 낮 동안 결제 자금을 빌려주는 제도예요. 건별로 바로 결제하는 시스템에서는 들어올 돈보다 나갈 돈이 먼저 생겨 잠시 자금이 모자랄 수 있어요. 이 공백을 메워 실시간 결제가 막힘없이 이어지게 해요."}, {"id": 460, "word": "일중당좌대출제도", "beforeLength": 422, "after": "영업시간 중 은행의 결제 자금이 잠시 모자랄 때 한국은행이 자동으로 빌려주는 제도예요. 한국은행 당좌예금 잔액보다 많은 돈을 보내야 하면 맡겨 둔 담보 범위 안에서 대출이 바로 실행돼요. 일정 한도를 넘는 금액에는 이자를 물려 은행이 이 대출에 너무 기대지 않게 해요."}, {"id": 461, "word": "자금결제시스템", "beforeLength": 169, "after": "은행 안에서 고객 계좌 사이의 이체만으로 돈 지급을 마무리하는 시스템이에요. 외환이나 증권 거래와 달리 같은 은행 안의 지급은 장부상 계좌 잔액만 옮기면 결제가 끝나요. 그래서 보통 각 은행이 고객 자금의 잔액과 입출금을 관리하는 회계 시스템과 같은 뜻으로 쓰여요."}, {"id": 462, "word": "자금관리서비스(CMS)공동망", "beforeLength": 429, "after": "여러 사람의 계좌에서 돈을 한꺼번에 걷거나 여러 계좌로 한꺼번에 보내는 공동 지급망이에요. 학원비나 회비는 납부자 계좌에서 자동으로 출금하고, 급여나 배당금은 다른 은행 계좌로 일괄 입금해요. 금융결제원이 운영하며 대량의 정기 입출금을 손쉽게 처리하게 해 줘요."}, {"id": 463, "word": "자금조달비용지수(COFIX)", "beforeLength": 370, "after": "주요 은행들이 예금이나 채권 등으로 돈을 모을 때 들인 평균 금리를 보여 주는 지수예요. 은행연합회가 여러 은행의 조달 금액과 금리를 가중평균해 정기적으로 공시해요. 변동금리 주택담보대출 금리의 기준으로 쓰여 이 지수가 오르면 대출 이자도 따라 올라요."}, {"id": 464, "word": "자기띠 카드", "beforeLength": 287, "after": "카드 뒷면의 검은 띠에 자성 물질을 입혀 카드 번호, 유효기간 같은 정보를 기록한 카드예요. 단말기에 긁으면 띠에 담긴 정보를 읽어 결제나 인증을 해요. 저장 용량이 작고 복제되기 쉬워 보안이 강한 IC 카드로 바뀌고 있어요."}, {"id": 465, "word": "자기자본비율", "beforeLength": 235, "after": "기업의 전체 자산 가운데 빌린 돈이 아닌 자기 돈, 즉 자기자본이 차지하는 비중이에요. 자기자본을 총자본으로 나눠 100을 곱해 구해요. 이자 부담 없이 오래 쓸 수 있는 돈이라 이 비율이 높을수록 재무구조가 안정적이라고 봐요."}, {"id": 466, "word": "자기자본이익률(ROE)", "beforeLength": 154, "after": "주주가 투자한 자기자본으로 1년 동안 순이익을 얼마나 벌었는지 보여 주는 수익성 지표예요. 당기순이익을 자기자본으로 나눠 구하며 높을수록 돈을 효율적으로 굴렸다는 뜻이에요. 다만 빚을 많이 써서 높아진 경우라면 그만큼 경영 위험도 커져요."}, {"id": 467, "word": "자동안정화장치", "beforeLength": 656, "after": "정부가 따로 정책을 결정하지 않아도 경기의 오르내림을 저절로 줄여 주는 제도적 장치예요. 불황에는 소득이 줄어 누진세 부담이 줄고 실업급여 지급이 늘어 소비가 덜 위축돼요. 반대로 호황에는 세금이 더 걷혀 과열을 식히며 정책 결정에 걸리는 시간도 들지 않아요."}, {"id": 468, "word": "자발적 실업", "beforeLength": 474, "after": "일할 능력과 기회는 있지만 지금의 임금이나 조건이 마음에 들지 않아 스스로 일하지 않는 실업이에요. 더 나은 일자리를 찾느라 잠시 쉬는 경우도 여기에 들어가요. 일하고 싶어도 일자리가 없어 생기는 비자발적 실업과 구분되며 완전고용 상태에서도 존재해요."}, {"id": 469, "word": "자본거래자유화", "beforeLength": 635, "after": "국경을 넘나드는 투자와 대출 같은 자본 이동에 대한 규제를 없애는 것을 말해요. 내국인이 해외에 투자하는 일과 외국인이 국내에 투자하는 일을 모두 자유롭게 허용하는 방향이에요. 자금 조달이 쉬워지는 장점이 있지만 돈이 갑자기 빠져나가 금융시장이 흔들릴 위험도 커져요."}, {"id": 470, "word": "자본생산성", "beforeLength": 281, "after": "생산에 투입한 자본의 양에 비해 얼마만큼의 산출물을 만들었는지 나타내는 비율이에요. 같은 설비로 더 많이 생산할수록 이 값이 높아져요. 투입한 노동 대비 산출을 보는 노동생산성과 짝을 이루며 함께 경제의 효율을 따지는 데 쓰여요."}, {"id": 471, "word": "자본시장법", "beforeLength": 674, "after": "증권거래법 등 자본시장 관련 6개 법을 하나로 합쳐 2009년부터 시행된 법이에요. 금융투자업을 투자매매, 투자중개, 집합투자 등 기능별로 나누고 같은 기능에는 같은 규제를 적용해요. 투자자 보호를 강화하고 금융투자회사가 여러 업무를 폭넓게 겸할 수 있게 하려는 목적이에요."}, {"id": 472, "word": "자본적정성", "beforeLength": 506, "after": "금융회사가 예상치 못한 손실을 견딜 만큼 충분한 자본을 갖추고 있는지의 정도예요. 자본은 자산에서 부채를 뺀 순자산으로, 손실이 나도 예금자 돈을 지키는 완충 역할을 해요. 은행은 보통 위험가중자산 대비 자기자본비율로 이를 평가받아요."}, {"id": 473, "word": "자본적지출", "beforeLength": 156, "after": "기계나 건물의 수명을 늘리거나 성능을 크게 높이려고 쓰는 돈이에요. 대규모 수리, 개조, 증축처럼 자산의 가치를 키우는 지출이 여기에 해당해요. 단순히 원래 상태를 유지하는 수리비와 달리 비용이 아니라 투자로 처리해요."}, {"id": 474, "word": "자산건전성 분류", "beforeLength": 284, "after": "금융회사가 가진 대출 등 자산을 돈을 돌려받을 가능성에 따라 등급으로 나누는 것이에요. 정상, 요주의, 고정, 회수의문, 추정손실의 5단계로 정기적으로 점검해 분류해요. 등급이 나쁠수록 손실에 대비한 대손충당금을 더 많이 쌓아야 해요."}, {"id": 475, "word": "자산유동화", "beforeLength": 490, "after": "대출채권이나 부동산처럼 바로 팔기 어려운 자산을 특수목적회사에 넘기고 이를 담보로 증권을 발행하는 것이에요. 그 자산에서 나오는 이자나 임대료 같은 현금흐름으로 증권 투자자에게 원리금을 줘요. 자산을 가진 회사는 자기 신용과 별개로 돈을 빨리 마련할 수 있어요."}, {"id": 477, "word": "자연실업률", "beforeLength": 640, "after": "경기가 정상일 때도 남아 있는, 물가를 자극하지 않고 유지할 수 있는 가장 낮은 실업률이에요. 이직 중인 사람이나 산업 구조 변화로 생기는 실업 때문에 0%가 될 수는 없어요. 1968년 프리드먼이 제시했으며 실업률을 이보다 억지로 낮추면 물가만 오른다고 봤어요."}, {"id": 478, "word": "자원민족주의", "beforeLength": 503, "after": "석유, 가스, 광물 같은 천연자원을 가진 나라가 자원 통제를 강화해 영향력을 키우려는 경향이에요. 외국 기업의 광산을 국유화하거나 개발 조건을 까다롭게 하고 수출량을 제한하는 방식이 대표적이에요. 자원을 수입하는 나라에는 공급 불안과 가격 상승의 원인이 돼요."}, {"id": 479, "word": "자유무역협정(FTA)", "beforeLength": 689, "after": "협정을 맺은 나라끼리 상품과 서비스 교역에 붙는 관세와 무역장벽을 없애는 약속이에요. 서로 시장을 열어 주면 기업은 수출이 쉬워지고 소비자는 수입품을 더 싸게 살 수 있어요. 다만 경쟁력이 약한 국내 산업은 피해를 볼 수 있어 보완 대책이 함께 논의돼요."}, {"id": 480, "word": "자유재", "beforeLength": 388, "after": "공기나 햇빛처럼 대가를 치르지 않고도 원하는 만큼 얻을 수 있는 재화예요. 희소하지 않아 값이 매겨지지 않으며 돈을 주고 사야 하는 경제재와 반대되는 개념이에요. 다만 생수를 사 마시듯 환경 변화로 경제재로 바뀌는 경우도 늘고 있어요."}, {"id": 481, "word": "작업증명", "beforeLength": 315, "after": "많은 컴퓨터 연산을 실제로 했다는 것을 증명해야 새 블록을 만들 수 있게 하는 블록체인 검증 방식이에요. 참여자들은 어려운 계산 문제를 먼저 풀려고 경쟁하고, 정답은 다른 사람이 쉽게 확인할 수 있어요. 비트코인 채굴이 대표적이며 전력을 많이 쓴다는 비판도 받아요."}, {"id": 482, "word": "잠재GDP성장률", "beforeLength": 471, "after": "노동과 자본을 무리 없이 활용해 물가를 계속 끌어올리지 않고 유지할 수 있는 생산 수준이 늘어나는 속도예요. 실제 성장률이 이보다 높으면 경기 과열과 물가 상승 압력이, 낮으면 경기 부진이 나타나기 쉬워요. 직접 관측되지 않아 추정 방법에 따라 값이 달라질 수 있어요."}, {"id": 483, "word": "잠재경제활동인구", "beforeLength": 251, "after": "공식 통계에서는 비경제활동인구로 잡히지만 사실상 일할 의사와 가능성이 있는 사람들이에요. 최근 구직활동을 했지만 당장 일할 수 없는 사람과, 구직활동은 안 했지만 일하길 원하고 당장 일할 수 있는 사람을 합쳐요. 공식 실업률이 놓치는 숨은 실업을 파악하는 데 쓰여요."}, {"id": 484, "word": "장기금융시장(자본시장)", "beforeLength": 265, "after": "만기 1년 이상의 채권이나 만기가 없는 주식이 거래되는 금융시장이에요. 기업과 정부가 설비 투자나 사업에 필요한 돈을 오랫동안 빌리거나 투자받는 통로로 쓰여요. 만기 1년 미만의 자금이 오가는 단기금융시장과 구분돼요."}, {"id": 485, "word": "장기침체", "beforeLength": 650, "after": "투자와 소비 수요가 부족해 경제가 오랫동안 잠재 수준보다 낮은 성장에 머무는 상태예요. 인구 증가가 둔화되고 기술 혁신이 줄면 투자할 곳이 사라져 금리를 낮춰도 경기가 잘 살아나지 않아요. 1938년 핸슨이 처음 썼고 2013년 서머스가 선진국 경제에 다시 적용하며 주목받았어요."}, {"id": 486, "word": "장내시장", "beforeLength": 503, "after": "한국거래소처럼 정해진 규칙과 표준화된 방식에 따라 증권이 거래되는 조직화된 시장이에요. 유가증권시장과 코스닥시장이 대표적이며 주식이 거래되려면 먼저 일정 요건을 갖춰 상장해야 해요. 거래 상대를 직접 찾지 않아도 되고 가격이 투명하게 공개돼요."}, {"id": 487, "word": "장단기금리차", "beforeLength": 1053, "after": "만기가 긴 채권의 금리에서 만기가 짧은 금리를 뺀 차이예요. 예를 들어 10년 국채 금리가 3.5%, 3년 국채 금리가 3%라면 차이는 0.5%포인트예요. 보통 장기금리가 더 높지만 이 차이가 줄거나 뒤집히면 경기 침체 신호로 해석하기도 해요."}, {"id": 488, "word": "장외시장", "beforeLength": 526, "after": "거래소 밖에서 증권사 같은 중개기관을 통해 사는 사람과 파는 사람이 개별적으로 거래하는 시장이에요. 채권이나 파생상품처럼 종류와 조건이 제각각이라 표준화하기 어려운 상품이 주로 여기서 거래돼요. 조건을 자유롭게 정할 수 있지만 가격이 덜 투명하고 상대방 위험이 있어요."}, {"id": 489, "word": "재산소득", "beforeLength": 693, "after": "예금, 채권, 주식 같은 금융자산이나 토지를 다른 사람이 쓰게 하고 그 대가로 받는 소득이에요. 금융자산에서는 이자와 배당이, 토지 같은 자연자원에서는 임대료가 생겨요. 일해서 받는 근로소득과 달리 자산을 가지고 있다는 이유로 생기는 소득이에요."}, {"id": 490, "word": "재정수지", "beforeLength": 619, "after": "정부가 한 해 동안 거둔 수입과 쓴 지출의 차이예요. 수입이 더 많으면 흑자, 지출이 더 많으면 적자이며 적자가 나면 국채를 발행해 메워요. 적자가 쌓이면 나랏빚이 늘어나므로 나라마다 적자 규모를 관리하는 기준을 두기도 해요."}, {"id": 491, "word": "재정정책", "beforeLength": 313, "after": "정부가 지출과 세금을 조절해 경기를 안정시키고 경제 목표를 이루려는 정책이에요. 불황에는 지출을 늘리거나 세금을 줄여 수요를 키우고, 과열 때는 반대로 해요. 금리와 돈의 양을 조절하는 중앙은행의 통화정책과 함께 경기 관리의 두 축이에요."}, {"id": 492, "word": "재정환율", "beforeLength": 483, "after": "두 통화를 직접 바꾸는 시장이 없을 때 각각의 달러 환율을 이용해 계산한 환율이에요. 원/달러가 1,400원이고 엔/달러가 140엔이면 원/엔 환율은 100엔당 1,000원이 돼요. 세계 외환거래 대부분이 달러를 중심으로 이뤄지기 때문에 이런 방식을 써요."}, {"id": 493, "word": "전방연쇄효과", "beforeLength": 381, "after": "어떤 산업의 생산이 늘 때 그 제품을 원재료로 쓰는 다른 산업에 미치는 파급 효과예요. 예를 들어 철강 생산이 늘어 공급이 원활해지면 이를 쓰는 자동차나 조선 산업의 생산도 쉬워져요. 반대로 원재료를 대 주는 산업에 미치는 영향은 후방연쇄효과라고 불러요."}, {"id": 494, "word": "전산업생산지수", "beforeLength": 498, "after": "광공업, 서비스업, 건설업, 공공행정 등 전체 산업의 생산 활동을 종합해 지수로 나타낸 것이에요. 업종마다 생산이 늘고 줄어 방향이 엇갈릴 때도 경제 전체의 흐름을 한눈에 볼 수 있어요. 경기가 좋아지는지 나빠지는지 판단할 때 자주 쓰이는 지표예요."}, {"id": 496, "word": "전월세 전환율", "beforeLength": 406, "after": "전세 보증금을 월세로 바꿀 때 줄어든 보증금에 적용하는 연 이율이에요. 1년치 월세를 줄어든 보증금으로 나눠 구하는데, 보증금을 1억 원 낮추고 월세 50만 원을 받으면 연 6%예요. 세입자는 전세와 월세 중 무엇이 유리한지, 집주인은 수익률을 따질 때 써요."}, {"id": 497, "word": "전자금융", "beforeLength": 582, "after": "컴퓨터와 통신 기술을 이용해 금융 업무를 자동화하고 전자적으로 처리하는 것을 말해요. 이용자는 직원을 직접 만나지 않고 인터넷뱅킹, 모바일뱅킹, ATM 같은 전자 장치로 금융 서비스를 써요. 시간과 장소의 제약을 줄이고 처리 비용을 낮춰 금융 거래 방식을 크게 바꿨어요."}, {"id": 498, "word": "전자금융공동망", "beforeLength": 426, "after": "인터넷뱅킹이나 모바일뱅킹으로 다른 은행에 돈을 보낼 때 은행 사이에서 거래를 중계해 주는 공동 전산망이에요. 타행 이체와 그 확인 조회, 자기앞수표 조회 같은 업무를 처리해요. 2001년 기존 전화 기반 공동망을 넓혀 만들었고 덕분에 은행이 달라도 바로 송금할 수 있어요."}, {"id": 499, "word": "전자단기사채", "beforeLength": 697, "after": "종이 실물 없이 전자 장부에 등록하는 방식으로 발행하고 거래하는 만기 1년 이내의 단기 회사채예요. 경제적 성격은 기업어음과 같지만 등록 기관의 장부로 관리돼 위조나 분실 위험이 없어요. 거래 정보가 투명하게 남아 기존 기업어음의 단점을 보완하려고 도입됐어요."}, {"id": 500, "word": "전자상거래", "beforeLength": 526, "after": "인터넷 같은 컴퓨터 네트워크를 통해 주문을 주고받으며 상품과 서비스를 사고파는 거래예요. 주문만 온라인이면 되고 결제나 배송까지 꼭 온라인으로 이뤄질 필요는 없어요. 처음에는 기업 간 거래가 많았지만 지금은 온라인 쇼핑처럼 소비자 대상 거래가 크게 늘었어요."}]$payload$::jsonb;
  v_bad text;
BEGIN
  PERFORM set_config('lock_timeout', '10s', true);
  IF jsonb_array_length(v_payload) <> 119 THEN RAISE EXCEPTION 'payload size must be 119'; END IF;
  IF (SELECT count(*) FROM public.words) <> 1233 THEN RAISE EXCEPTION 'words count changed since review'; END IF;
  IF to_regclass('public.words_detailed_meaning_backup_v1') IS NULL THEN RAISE EXCEPTION 'backup table missing; apply revision v1 first'; END IF;
  IF EXISTS (SELECT 1 FROM public.words_detailed_meaning_backup_v1 WHERE id IN (377,378,379,380,381,382,383,384,385,386,387,388,389,390,391,392,393,394,395,396,397,398,399,400,402,403,404,405,406,407,408,409,410,411,412,413,414,415,416,417,418,419,420,421,422,423,424,425,427,428,429,430,431,432,433,434,435,436,437,438,439,440,441,442,443,444,445,446,447,448,449,450,452,453,454,455,456,457,458,459,460,461,462,463,464,465,466,467,468,469,470,471,472,473,474,475,477,478,479,480,481,482,483,484,485,486,487,488,489,490,491,492,493,494,496,497,498,499,500)) THEN
    RAISE EXCEPTION 'backup already has rows of batch 4; it was applied before';
  END IF;

  SELECT string_agg(r.id::text, ',') INTO v_bad
  FROM jsonb_to_recordset(v_payload) AS r(id integer, word text, "beforeLength" integer, after text)
  LEFT JOIN public.words w ON w.id = r.id
  WHERE w.id IS NULL OR w.word IS DISTINCT FROM r.word OR char_length(w.detailed_meaning) <> r."beforeLength";
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'rows changed since review: %', v_bad; END IF;

  INSERT INTO public.words_detailed_meaning_backup_v1 (id, word, detailed_meaning)
  SELECT w.id, w.word, w.detailed_meaning FROM public.words w WHERE w.id IN (377,378,379,380,381,382,383,384,385,386,387,388,389,390,391,392,393,394,395,396,397,398,399,400,402,403,404,405,406,407,408,409,410,411,412,413,414,415,416,417,418,419,420,421,422,423,424,425,427,428,429,430,431,432,433,434,435,436,437,438,439,440,441,442,443,444,445,446,447,448,449,450,452,453,454,455,456,457,458,459,460,461,462,463,464,465,466,467,468,469,470,471,472,473,474,475,477,478,479,480,481,482,483,484,485,486,487,488,489,490,491,492,493,494,496,497,498,499,500);

  UPDATE public.words w SET detailed_meaning = r.after
  FROM jsonb_to_recordset(v_payload) AS r(id integer, word text, "beforeLength" integer, after text)
  WHERE w.id = r.id;

  IF (SELECT count(*) FROM public.words w JOIN jsonb_to_recordset(v_payload) AS r(id integer, word text, "beforeLength" integer, after text) ON r.id = w.id
      WHERE w.detailed_meaning = r.after) <> 119 THEN
    RAISE EXCEPTION 'updated row count mismatch';
  END IF;
  IF (SELECT count(*) FROM public.words_detailed_meaning_backup_v1 WHERE id IN (377,378,379,380,381,382,383,384,385,386,387,388,389,390,391,392,393,394,395,396,397,398,399,400,402,403,404,405,406,407,408,409,410,411,412,413,414,415,416,417,418,419,420,421,422,423,424,425,427,428,429,430,431,432,433,434,435,436,437,438,439,440,441,442,443,444,445,446,447,448,449,450,452,453,454,455,456,457,458,459,460,461,462,463,464,465,466,467,468,469,470,471,472,473,474,475,477,478,479,480,481,482,483,484,485,486,487,488,489,490,491,492,493,494,496,497,498,499,500)) <> 119 THEN
    RAISE EXCEPTION 'backup row count mismatch';
  END IF;
END
$apply_v2_4$;
